PATH = "pwa/data/notes/cn_notes.json"
NEW = {}

NEW["1.1.5 计算机网络的分类"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>按使用者分类（教材补充）</b>：<ul><li><b>公用网（Public Network）</b>：由<b>电信运营商出资建设</b>、面向公众开放，任何愿意遵守规定并缴纳费用的用户均可接入；</li><li><b>专用网（Private Network）</b>：由<b>特定单位</b>为满足自身业务需求而建设、<b>仅限内部使用</b>、不对外服务（如铁路、电力、军队专网）。</li></ul></li><li>对照：按访问方式分类另有“接入网/本地网”等；按拓扑分类见教材四种基本拓扑（总线/星形/环形/网状：网状可靠性高、容错强，但控制复杂、线路成本高，用于广域网）。</li></ul>"""

NEW["2.1.3 编码与调制"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>编码全家福（补齐 NRZ 家族）</b>：数字数据编码为数字信号（基带传输）的常用方式：<ul><li><b>归零 RZ</b>：高电平=1、低电平=0（或反之），<b>每个码元中间跳变回零电平</b>（“归零”）→ 自带时钟可实现<b>自同步</b>；但归零占用带宽、传输效率低。</li><li><b>非归零 NRZ</b>：整个码元周期都用高/低电平表示数据、<b>不归零</b> → <b>编码效率最高</b>；但<b>缺乏内在时钟</b>、需额外时钟线同步（2015 真题考 NRZ 波形）。</li><li><b>反向非归零 NRZI</b>：<b>以码元起始处是否有跳变</b>表示数据（<b>无跳变=1，有跳变=0</b>，按协议约定）——跳变本身可用于<b>辅助时钟恢复</b>，兼顾 NRZ 的高效率与一定的自同步能力、避免 RZ 的带宽浪费（USB 等使用）。</li><li>对照：<b>曼彻斯特</b>每个码元<b>中间必跳变</b>（跳变即时钟+数据）；<b>差分曼彻斯特</b>看<b>起始处</b>有无跳变（起始跳变=0）。<b>NRZI 与差分曼彻斯特同属“差分/跳变编码”</b>（看起始跳变），区别是 NRZI 码元中间无强制跳变。</li></ul></li></ul>"""

NEW["2.2.1 双绞线、同轴电缆、光纤与无线传输介质"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>双绞线的两种（教材补充）</b>：双绞线 = 两根相互绝缘、按规则<b>绞合</b>的铜导线，绞合可<b>减少相邻导线间的电磁干扰</b>；按有无屏蔽层分：<ul><li><b>屏蔽双绞线（STP）</b>：外面加一层<b>金属丝编织屏蔽层</b> → 抗干扰更强；</li><li><b>非屏蔽双绞线（UTP）</b>：无屏蔽层，价格更低、更常用（5 类/超 5 类等）。</li></ul></li><li><b>同轴电缆两个规格</b>：<b>50Ω</b> 用于基带数字信号（早期局域网）；<b>75Ω</b> 用于宽带模拟信号（有线电视）。得益于外导体屏蔽，抗干扰好、速率较高。</li><li>双绞线价格低廉、既可模拟又可数字传输，通信距离几 km~数十 km；远距时模拟要<b>放大器</b>、数字要<b>中继器</b>（整形）。</li></ul>"""

NEW["3.4.2 可靠传输机制"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>NAK（否定确认）可加速重传（教材补充）</b>：接收方发现收到的帧出错时，<b>可立即向发送方发送否定帧 NAK</b>，请求重传出错的帧——<b>不必等超时</b>，比“超时后重传”更快。<b>SR（选择重传）</b>协议支持接收方用 NAK 只重传出错帧。</li><li>对照：GBN 出错时接收方丢弃出错帧及后续帧并不发 NAK，只能等发送方超时后从出错帧起全部重传。</li></ul>"""

NEW["3.5.2 随机访问介质访问控制"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>ALOHA 的两种（补齐区别）</b>：<ul><li><b>纯 ALOHA</b>：任一站点需要发送时<b>想发就发</b>，不检测信道；一段时间未收到确认即认为冲突，<b>等待随机时间后重传</b>。若两站帧在时间上部分重叠即冲突。</li><li><b>时隙 ALOHA（分隙 ALOHA）</b>：<b>把时间划分为等长的时隙（Slot）</b>，各站<b>只能在时隙开始的时刻</b>发送——冲突只会在同一时隙发生，<b>冲突概率减半、信道利用率翻倍</b>（纯 ALOHA 最大利用率 ≈ 1/(2e)，时隙 ALOHA ≈ 1/e）。</li></ul></li><li>随机访问 = 通过<b>争用</b>获得信道使用权，不预留时间也不独占频段（与静态划分信道相对）。</li></ul>"""

NEW["3.6.3 IEEE 802.11无线局域网"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>802.11 的两种组网模式</b>：<ul><li><b>有固定基础设施</b>：<b>基本服务集 BSS</b>（以 AP 基站为中心）、多个 BSS 经<b>分配系统 DS</b> 构成<b>扩展服务集 ESS</b>；移动站跨 BSS 移动称为<b>漫游</b>（仍可保持通信、换 AP）。</li><li><b>无固定基础设施：自组网络（ad hoc network）</b>——<b>没有 AP</b>，由若干地位平等的移动站临时组成的<b>对等网络</b>，各节点<b>兼具终端与路由器</b>功能（需转发他人数据、参与路由发现与维护）、拓扑频繁变化。</li><li><b>自组网络 ≠ 移动 IP</b>：移动 IP 依赖固定网络路由基础设施支持漫游；自组网络是<b>分布式无线自治系统</b>，有专用路由协议、可独立于互联网运行。</li></ul></li><li><b>MAC 子层两种介质访问控制方式</b>：<ul><li><b>分布式协调功能（DCF）</b>：<b>无中心控制</b>、各站争用信道（CSMA/CA）；<b>必须实现</b>、目前广泛使用；</li><li><b>点协调功能（PCF）</b>：由 <b>AP 集中控制</b>、用类似探询的方式把发送权轮流分配给各站以避免冲突；<b>可选方式</b>、实际很少用。</li></ul></li><li><b>帧间间隔用途（补全）</b>：<b>DIFS</b>（最长，DCF 下发数据/管理帧）、<b>PIFS</b>（中等，PCF 用）、<b>SIFS</b>（最短，用于 ACK/CTS/分片帧/AP 探询响应等同一对话的连续帧）。</li></ul>"""

NEW["3.6.4 VLAN基本概念与基本原理"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>汇聚链路（Trunk Link，干线链路）</b>：连接<b>两台交换机之间的链路</b>。跨交换机的同 VLAN 通信必须走干线：<ul><li>源交换机转发跨交换机帧时，<b>先插入 VLAN 标签（802.1Q 帧）再经干线传输</b>，否则对端无法判断该帧属于哪个 VLAN；</li><li>目的交换机向主机转发前<b>剥离 VLAN 标签</b>，主机收到的是标准以太网帧；</li><li>因此<b>干线上传输的是 802.1Q 帧、接入链路传标准以太网帧</b>。</li></ul></li><li>VLAN 范围可跨越多个交换机（都支持 VLAN 时），不同 VLAN 仍是独立广播域、二层不能互通。</li></ul>"""

NEW["4.2.2 IPv4地址"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>IP 地址的管理（教材补充）</b>：IP 地址的分配与协调由<b>互联网名称与数字地址分配机构（ICANN）</b>统筹（顶级地址由 IANA 管理、按区域分配给各 RIR，逐级下放到 ISP 与用户）。<b>私有地址与公网地址的划分也由此体系配合 NAT 实施</b>。</li><li>补充：回环测试地址（Loopback Test）127.0.0.0/8 用于本机自测、不能作为源/目的地址出现在网络中。</li></ul>"""

NEW["4.4.4 开放最短路径优先协议"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>LSDB 与路由表生成（补齐机制）</b>：各路由器频繁交换链路状态后，最终都能构建出<b>一致的链路状态数据库（LSDB）</b>；每个路由器基于 LSDB 用 <b>Dijkstra</b> 算到各目的的最优路径、生成自己的路由表。<b>注意：路由表不存完整路径、只存“下一跳”</b>——到了下一跳才知道再下一跳怎么走。</li><li><b>OSPF 报文的其它特性</b>：支持<b>负载分担</b>（到同一目的存在多条代价相同路径时均衡分流）；具备<b>鉴别功能</b>（仅在可信路由器间交换链路状态信息）；支持 VLSM 与无分类编址 CIDR；<b>每条链路状态通告（LSA）携带 32 位序号</b>，序号越大状态越新。</li></ul>"""

NEW["4.4.5 边界网关协议"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>BGP 的两个核心属性（2024 考点）</b>：BGP 路由 = &lt;前缀, <b>AS-PATH</b>, <b>NEXT-HOP</b>&gt;：<ul><li><b>AS-PATH（自治系统路径）</b>：记录该路由<b>所经过的 AS 序列</b>；每个自治系统由全局唯一的<b>自治系统号（ASN）</b>标识，路由每经过一个 AS 就把它的 ASN 追加进 AS-PATH——它只指明经过哪些 AS、<b>不指明具体路由器</b>；</li><li><b>NEXT-HOP（下一跳）</b>：去往目的网络时应使用的下一跳地址，通常是<b>通告该路由的邻居 AS 边界路由器与本 AS 直连的接口 IP</b>。</li></ul></li><li><b>BGP 路由选择优先级</b>（多条候选路由时）：①选<b>本地偏好（LOCAL-PREF）值最高</b>的（管理员按策略设置）；②本地偏好相同则选 <b>AS-PATH 最短（AS 跳数最少）</b>的；③再按起点类型/其他属性比较。</li><li><b>BGP 会话</b>：AS 内边界路由器之间、以及跨越 AS 的 BGP 路由器之间，通过<b>端口 179 的半永久 TCP 连接</b>交换 BGP 路由——每对互连路由器称为<b>BGP 对等方</b>，该 TCP 连接称为 BGP 会话（跨 AS 的为外部 eBGP、AS 内的为内部 iBGP）。</li></ul>"""

NEW["5.1.2 传输层的寻址与端口"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>常用 UDP 熟知端口（补充）</b>：除 TCP 端口外，常见的 <b>UDP</b> 应用端口也要会认：<b>DNS 53、TFTP 69（简单文件传送协议）、SNMP 161（简单网络管理协议）、RIP 520</b> 等——它们都对应 <b>无连接服务</b>（5.1.3 考点：“以下哪种协议使用 UDP”——TFTP/DHCP/SNMP/RIP 均用 UDP）。</li><li>记忆：需要可靠连接的用 TCP（FTP 21/20、TELNET 23、SMTP 25、POP3 110、HTTP 80、HTTPS 443），追求简单/实时/组播的用 UDP（DNS、TFTP、SNMP、DHCP、RIP）。</li></ul>"""

NEW["6.2.1 层次域名空间"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>顶级域名（TLD）三大类（教材补充）</b>：<ul><li><b>国家顶级域名（ccTLD）</b>：代表国家/地区，如 .cn（中国）、.us（美国）；</li><li><b>通用顶级域名（gTLD）</b>：.com（公司）、.net（网络服务机构）、.org（非营利组织）、.edu（教育机构）、.gov（政府机构）等；</li><li><b>基础结构域名（arpa）</b>：用于<b>反向域名解析</b>（把 IP 地址转换为域名）。</li></ul></li><li><b>域名标号规则</b>：英文字母<b>不区分大小写</b>；标号中除<b>连字符(-)</b>外不得使用其它标点符号；<b>每个标号 ≤63 字符、整个域名（含分隔点）≤255 字符</b>；<b>级别最低的写在最左边</b>、顶级域名在最右边。</li></ul>"""

NEW["6.2.2 域名服务器"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>域名的分层管理（教材补充）</b>：各级域名由<b>上一级域名管理机构</b>管理——<b>顶级域名由 ICANN 管理</b>；国家顶级域名（.cn）下的二级域名由相应国家自行规定管理；组织还可把所辖域划分子域并<b>委托给其它组织管理</b>（如中国把 edu.cn 子域<b>授权给 CERNET</b>管理）。</li><li><b>区（Zone）</b>：一个域名服务器负责管理（具有管理权限）的范围称为<b>区</b>，<b>区的范围 ≤ 域</b>；一个区内所有结点必须可达、是其管辖范围。</li></ul>"""

NEW["6.5.2 HTTP协议"] = """<h4>📌 教材知识点补缺</h4><ul><li><b>HTTP 的报文结构（教材补充，2015 考点）</b>：HTTP 是<b>面向文本的（Text-Oriented）</b>——报文中每个字段均为 <b>ASCII 字符串</b>、字段长度不固定。报文分两类：<ul><li><b>请求报文</b>（客户→服务器）：开始行叫<b>请求行</b>；</li><li><b>响应报文</b>（服务器→客户）：开始行叫<b>状态行</b>。</li></ul>两类报文都由 <b>开始行 + 首部行 + 实体主体</b> 三部分组成，仅开始行不同：<ul><li><b>开始行</b>：三个字段之间以<b>空格分隔</b>、<b>行末以回车换行符（CRLF）结束</b>；</li><li><b>首部行</b>：向对方传递浏览器/服务器/报文主体的附加信息，可多行也可为空；每行形如“字段名：值”，行末同样以 CRLF 结束；首部行结束后空一行再是实体主体。</li></ul></li></ul>"""

def main():
    dry = "--dry" in sys.argv
    raw = open(PATH, "rb").read()
    d = json.loads(raw.decode("utf-8"))
    done, missing = [], []
    for c in d["chapters"]:
        for s in c["sections"]:
            for ss in s.get("subsections", []):
                sec = ss["section"].strip()
                if sec not in NEW:
                    continue
                h = ss.get("html") or ""
                if "📌 教材知识点补缺" in h:
                    done.append(sec)  # 幂等:已补过视为命中
                    continue
                ss["html"] = h + NEW[sec]
                done.append(sec)
    for k in NEW:
        if k not in done:
            missing.append(k)
    print(f"补写 {len(done)} 个小节 | 未命中 {len(missing)}")
    for m in missing:
        print("  [未命中]", m)
    if dry:
        print("dry-run 结束,未落盘")
        return
    out = (json.dumps(d, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    open(PATH, "wb").write(out)
    print("已写入")

if __name__ == "__main__":
    main()